var m11 = {
 id:"m11", n:11, title:"Estado de choque", icon:"drop",
 intro:"Estado de choque não é susto, e também não é choque elétrico. É quando o corpo não consegue levar sangue e oxigênio suficientes aos órgãos. Pode começar após hemorragia, queimadura grande, alergia grave ou infecção. Reconhecer cedo e pedir ajuda salva vidas.",
 objectives:["Definir estado de choque e diferenciá-lo de susto","Citar as principais causas","Reconhecer sinais e sintomas","Aplicar os cuidados iniciais seguros","Explicar por que o atendimento rápido é essencial"],
 sections:[
  {id:"m11s1", title:"O que é o estado de choque", body:[
   "Estado de choque é uma condição grave em que a circulação do sangue não consegue entregar oxigênio suficiente às células do corpo. Os órgãos, como cérebro, coração e rins, começam a falhar. O corpo tenta compensar, acelerando o coração e desviando sangue para os órgãos mais importantes, por isso a pele fica pálida e fria.",
   "No dia a dia, usamos 'tomar um choque' para falar de susto, mas o estado de choque é médico e não passa sozinho. Se não tratado, evolui rápido e pode levar à parada cardíaca. Quanto mais cedo a equipe de saúde atua, maiores as chances de recuperação."
  ]},
  {id:"m11s2", title:"Principais causas", body:[
   "A causa mais conhecida é a perda de sangue, em hemorragias externas ou internas, depois de quedas, acidentes ou cortes profundos. Outras causas são queimaduras extensas (perda de líquidos), desidratação grave, problemas do coração, infecções graves e reações alérgicas intensas (anafilaxia), em que o corpo reage de forma exagerada a um alimento, picada ou medicamento.",
   "Em todos os casos, o resultado é parecido: pouco sangue circulando ou vasos incapazes de manter a pressão. Nem sempre a causa é visível. Uma pessoa pode ter hemorragia interna, sem sangue aparecendo. Por isso, observe sinais gerais e sempre considere o mecanismo do acidente."
  ]},
  {id:"m11s3", title:"Sinais e sintomas", body:[
   "Os sinais clássicos são: pele pálida, fria e suada, pulso rápido e fraco, respiração rápida, sede, tontura, fraqueza, ansiedade, agitação ou confusão e, depois, sonolência e perda de consciência. Lábios e pontas dos dedos podem ficar azulados ou arroxeados.",
   "Esses sinais podem surgir aos poucos. Uma vítima de acidente pode, no início, estar consciente e conversando, e piorar em minutos. Por isso, observe sempre de novo. Se você notar pele fria, suor e aceleração do coração em alguém ferido, trate como estado de choque e acione 192 imediatamente."
  ], callout:{type:"warn", text:"Uma vítima pode parecer estável e piorar rápido. Observe continuamente até a equipe chegar."}},
  {id:"m11s4", title:"Cuidados iniciais", body:[
   "Garanta a segurança da cena e ligue 192. Se houver sangramento visível, controle com pressão direta usando pano limpo. Deite a vítima e, se não houver suspeita de trauma na cabeça, coluna ou pernas, nem dificuldade para respirar, eleve as pernas cerca de 30 cm para facilitar o retorno do sangue ao coração.",
   "Aqueça a vítima com cobertor ou casaco, pois ela perde calor com facilidade. Afrouxe roupas apertadas e mantenha-a calma. Não ofereça nada por via oral, nem água, pois ela pode precisar de cirurgia ou ter vômitos. Se ficar inconsciente e não respirar normalmente, inicie a RCP.",
   "Evite movimentar a vítima sem necessidade, principalmente em casos de trauma. Converse e tranquilize. Informe à equipe o que aconteceu, desde quando e quais cuidados você fez. O tempo é essencial: o atendimento rápido, com reposição de líquidos e controle da causa, só pode ser feito por profissionais."
  ]}
 ],
 examples:[
  {title:"Queda de patins", env:"parque", text:"Um colega cai de patins e corta fortemente a perna. Ele fica pálido, suado e diz que está com sede e tonto. Você liga 192, comprime o corte com pano limpo, deita o colega e aquece com um casaco. Como a perna machucada pode estar fraturada, você não eleva as pernas e nada dá para ele beber. Fala com ele até a equipe chegar."},
  {title:"Alergia no lanche", env:"escola", text:"Após comer um alimento, uma colega tem o rosto inchado, falta de ar, pele fria e tontura. Isso pode ser reação alérgica grave. Um adulto liga para o 192 e você a deixa deitada, na posição mais confortável para respirar, e acompanha o estado dela. Não oferece comida nem bebida. Se ela tiver medicamento próprio de emergência, apenas ajude conforme a orientação do adulto responsável e do atendente do 192."}
 ],
 summary:["Estado de choque: órgãos sem oxigênio suficiente por falha na circulação.","Causas: hemorragia, queimaduras, desidratação, alergia grave, infecção, problemas no coração.","Sinais: pele pálida, fria e suada; pulso rápido e fraco; respiração rápida; sonolência.","Ligue 192, deite, aqueça e controle sangramento visível.","Eleve as pernas só se não houver trauma de cabeça, coluna ou pernas, nem dificuldade para respirar.","Nada por via oral; atendimento rápido salva vidas."],
 extras:[
  {title:"Mito x Verdade", text:"Mito: 'Dar água ou café ajuda a pessoa em choque.' Verdade: nada por via oral. Pode causar vômito e atrapalhar procedimentos."},
  {title:"Curiosidade", text:"O corpo reage ao choque desviando sangue da pele para órgãos vitais. É por isso que a pele fica fria e pálida."},
  {title:"Checklist rápido", text:"Cena segura, 192, controlar sangramento, deitar, aquecer, elevar pernas se permitido, nada por via oral, observar sempre."}
 ],
 cards:[
  {q:"O que é estado de choque?", a:"Falha na circulação, com órgãos recebendo pouco oxigênio. É emergência médica grave."},
  {q:"Choque é igual a susto?", a:"Não. Susto é emocional; estado de choque é falha circulatória grave."},
  {q:"Sinais clássicos", a:"Pele pálida, fria e suada, pulso rápido e fraco, respiração rápida e sonolência."},
  {q:"Causas comuns", a:"Hemorragia, queimaduras extensas, desidratação, alergia grave, infecção e problemas cardíacos."},
  {q:"Elevar as pernas, quando?", a:"Se não houver trauma de cabeça, coluna ou pernas, nem dificuldade para respirar."},
  {q:"Pode oferecer água?", a:"Não. Nada por via oral: há risco de vômito e a vítima pode precisar de cirurgia."}
 ],
 activity:[
  {id:"m11a1", type:"mc", q:"O que descreve melhor o estado de choque?", options:["Um susto emocional passageiro","Uma falha circulatória que reduz o oxigênio nos órgãos","Uma reação normal ao frio","Uma dor de cabeça forte"], answer:1, exp:"O estado de choque é uma emergência médica em que a circulação não supre os órgãos."},
  {id:"m11a2", type:"tf", q:"Uma vítima com sinais de choque deve receber água para se recuperar.", answer:false, exp:"Nada por via oral. Pode vomitar ou precisar de cirurgia."},
  {id:"m11a3", type:"short", q:"Qual número você liga para pedir ajuda médica de urgência?", answers:["192"], exp:"O 192 aciona o SAMU, que orienta e envia a equipe."},
  {id:"m11a4", type:"match", q:"Relacione o sinal ou conduta com o significado.", pairs:[["Pele pálida, fria e suada","Sinal de estado de choque"],["Sangramento visível","Pressão direta com pano limpo"],["Vítima com frio","Aquecer com cobertor"],["Suspeita de trauma nas pernas","Não elevar as pernas"]], exp:"Reconhecer sinais e agir sem agravar lesões é o essencial do socorrista leigo."},
  {id:"m11a5", type:"seq", q:"Ordene os cuidados iniciais com a vítima em estado de choque.", items:["Garantir a segurança da cena","Ligar 192","Controlar sangramento visível","Deitar e aquecer a vítima","Observar continuamente até a equipe chegar"], exp:"Cena segura e pedido de ajuda vêm antes; depois, controle do sangramento, conforto e observação constante."},
  {id:"m11a6", type:"essay", q:"Explique por que o atendimento rápido é tão importante no estado de choque.", exp:"Esperado: os órgãos ficam sem oxigênio e podem sofrer danos irreversíveis ou parar; o quadro piora rápido; só profissionais podem repor líquidos e tratar a causa; o socorrista ajuda ligando cedo e dando cuidados básicos."}
 ],
 assessment:[
  {id:"m11s1", type:"mc", q:"Qual conjunto de sinais sugere estado de choque?", options:["Pele corada, calma e pulso lento","Febre leve e coceira","Pele fria e suada, pulso rápido e fraco","Dor de garganta e tosse seca"], answer:2, exp:"Pele pálida, fria e suada, pulso rápido e fraco e respiração rápida são sinais clássicos."},
  {id:"m11s2", type:"mc", q:"Qual destas pode ser causa de estado de choque?", options:["Hemorragia importante","Boa noite de sono","Alimentação saudável","Caminhada leve"], answer:0, exp:"A perda de sangue reduz o volume circulante e leva ao choque."},
  {id:"m11s3", type:"mc", q:"Quando NÃO se deve elevar as pernas da vítima?", options:["Quando ela está pálida","Quando há suspeita de trauma de cabeça, coluna ou pernas","Quando ela tem frio","Quando ela está acordada"], answer:1, exp:"Nesses casos, movimentar pode agravar a lesão. Também não elevar se houver dificuldade para respirar."},
  {id:"m11s4", type:"tf", q:"Mesmo que a vítima pareça estável, ela pode piorar rapidamente, e por isso deve ser observada continuamente.", answer:true, exp:"O choque pode evoluir em minutos. Observe sempre até a chegada da equipe."},
  {id:"m11s5", type:"err", q:"Encontre a conduta INCORRETA no estado de choque.", items:["Ligar 192","Controlar o sangramento visível","Aquecer a vítima","Dar bastante água para reidratar"], answer:3, exp:"Nada por via oral. Água pode causar vômito e atrapalhar o tratamento."},
  {id:"m11s6", type:"short", q:"Qual cuidado ajuda a vítima a manter a temperatura corporal?", answers:["aquecer","cobertor","cobrir","agasalh"], exp:"Aquecer com cobertor ou casaco evita a perda de calor, que piora o quadro."}
 ]
};

var m12 = {
 id:"m12", n:12, title:"Remoção e transporte de vítimas", icon:"move",
 intro:"Mover uma vítima parece ser a ajuda mais natural, mas pode ser a mais perigosa. Uma movimentação errada pode transformar uma lesão simples em uma lesão permanente na coluna. Neste módulo, você aprende quando NÃO mover, quando é preciso mover e como fazer isso com o mínimo de risco.",
 objectives:["Explicar por que não se deve mover a vítima sem necessidade","Avaliar quando a movimentação é indispensável","Descrever os riscos da movimentação inadequada","Conhecer noções de transporte e equipamentos","Reconhecer a importância de profissionais capacitados"],
 sections:[
  {id:"m12s1", title:"Regra de ouro: não mover sem necessidade", body:[
   "Remoção é o ato de tirar a vítima de um local; transporte é levá-la até um serviço de saúde. A regra geral para o socorrista leigo é: não mova a vítima sem necessidade. Muitas lesões não são visíveis, como fraturas na coluna. Um movimento brusco pode lesionar a medula e causar paralisia permanente.",
   "O melhor, em geral, é manter a vítima no lugar, tranquilizá-la, ligar 192 e esperar os profissionais, que têm equipamentos e treinamento. Isso vale especialmente para quedas de altura, acidentes de trânsito, mergulhos em águas rasas e qualquer pancada forte na cabeça, no pescoço ou nas costas."
  ]},
  {id:"m12s2", title:"Quando é preciso mover", body:[
   "A movimentação só se justifica diante de perigo imediato para a vida: fogo, risco de desabamento, risco de novas colisões no trânsito, vazamento de gás ou fumaça, risco de afogamento, ou quando é necessário para fazer RCP, por exemplo, se a vítima está em um local que não permite compressões.",
   "Antes de decidir, avalie sua segurança: se você não consegue mover sem se colocar em perigo, não mova e peça ajuda. Se for necessário mover, faça o mínimo e o mais rápido possível, só até um local seguro. Lembre-se de que a sua segurança vem primeiro, pois um socorrista machucado vira mais uma vítima."
  ], callout:{type:"warn", text:"Dúvida sobre a necessidade de mover? Não mova. Ligue 192 e siga as orientações do atendente."}},
  {id:"m12s3", title:"Como mover com menos risco", body:[
   "Quando for indispensável, a técnica básica é o arrasto pelo eixo longo do corpo, puxando a vítima pelos ombros, pela cabeça, ou pelas roupas na altura dos ombros, mantendo cabeça, pescoço e tronco alinhados, como se fossem uma peça só. Evite torcer, dobrar ou levantar a vítima de forma brusca.",
   "Vítimas conscientes e sem suspeita de lesão grave podem, às vezes, ser ajudadas a caminhar com apoio. Mas, diante de suspeita de coluna, siga a regra de mover só em perigo imediato. O capacete de motociclista não deve ser retirado pelo leigo, salvo necessidade de via aérea ou RCP e, se possível, só por quem foi treinado. O capacete protege e mantém o pescoço alinhado."
  ]},
  {id:"m12s4", title:"Equipamentos, transporte e profissionais", body:[
   "As equipes de emergência usam equipamentos como colar cervical, prancha longa, maca, coletes de imobilização e macas especiais. Esses itens mantêm a coluna alinhada durante a remoção. O leigo pode ver essas peças, mas o uso correto exige treinamento, pois um colar mal posicionado pode atrapalhar a respiração ou piorar a lesão.",
   "O transporte da vítima em carro particular só deve ser considerado quando o 192 orientar ou quando não houver outra opção, e com cuidado. A ambulância leva profissionais, oxigênio e equipamentos, e a equipe pode agir durante o trajeto. Por isso, chamar o 192 e esperar quem é capacitado é, quase sempre, a melhor decisão. Siga o protocolo ensinado pelo instrutor presencial."
  ]}
 ],
 examples:[
  {title:"Queda da árvore", env:"parque", text:"Um colega cai de uma árvore alta, está acordado, mas reclama de dor nas costas e não sente as pernas. Você não tenta levantá-lo. Liga 192, pede que ele não se mexa e segura a cabeça sem tracionar, mantendo-a alinhada, enquanto fala com ele. Os profissionais chegam com prancha e colar. Mover sem necessidade poderia causar lesão permanente na coluna."},
  {title:"Acidente de moto", env:"rua", text:"Um motociclista cai e fica no chão com o capacete. Ele respira e está consciente. Você liga 192, sinaliza o local para evitar novos acidentes e não retira o capacete. Se ele parar de respirar, o capacete pode ser retirado, de preferência por quem foi treinado, para permitir a RCP. Se houver risco de incêndio, o arrasto pelo eixo do corpo é a opção."}
 ],
 summary:["Regra de ouro: não mover a vítima sem necessidade.","Mover só diante de perigo imediato: fogo, desabamento, trânsito, gás.","Arrasto pelo eixo longo, com cabeça, pescoço e tronco alinhados.","Movimento errado pode causar lesão permanente na coluna.","Leigo não retira capacete, salvo via aérea ou RCP, preferencialmente por quem foi treinado.","Prefira esperar a equipe do 192 com seus equipamentos."],
 extras:[
  {title:"Mito x Verdade", text:"Mito: 'Levar logo no meu carro é mais rápido.' Verdade: pode agravar lesões e atrasar o tratamento. O 192 leva profissionais e equipamentos."},
  {title:"Checklist rápido", text:"Cena segura, há perigo imediato? Se não, não mover. Ligar 192. Se for preciso mover, arrastar pelo eixo e só até um local seguro."},
  {title:"Para saber mais", text:"Cursos presenciais ensinam técnicas de rolamento, imobilização e uso de equipamentos, com prática supervisionada em manequins e colegas, sob orientação de instrutor."}
 ],
 cards:[
  {q:"Regra geral de movimentação", a:"Não mover a vítima sem necessidade, pois lesões ocultas podem piorar."},
  {q:"Quando mover é justificável?", a:"Perigo imediato: fogo, desabamento, trânsito, gás, ou necessidade de RCP."},
  {q:"Arrasto pelo eixo longo", a:"Puxar mantendo cabeça, pescoço e tronco alinhados, o mínimo e só até um local seguro."},
  {q:"Risco da movimentação errada", a:"Lesão da coluna e da medula, com possível paralisia permanente."},
  {q:"Capacete de motociclista", a:"O leigo não retira, salvo via aérea ou RCP, preferencialmente por quem foi treinado."},
  {q:"Por que chamar o 192?", a:"A equipe tem treino e equipamentos como prancha e colar para mover com segurança."}
 ],
 activity:[
  {id:"m12a1", type:"mc", q:"Qual é a regra geral para o socorrista leigo em relação a mover a vítima?", options:["Sempre mover para um local confortável","Não mover sem necessidade","Sentar a vítima","Levar de carro particular imediatamente"], answer:1, exp:"Sem perigo imediato, mantenha a vítima onde está e espere a equipe."},
  {id:"m12a2", type:"tf", q:"Em caso de incêndio no local, pode ser necessário mover a vítima mesmo com risco de lesão.", answer:true, exp:"Fogo é perigo imediato. Se for seguro para você, mova pelo eixo do corpo até um local seguro."},
  {id:"m12a3", type:"short", q:"Qual parte do corpo corre maior risco de lesão grave quando se move mal uma vítima com suspeita de trauma?", answers:["coluna","medula"], exp:"A coluna e a medula espinhal podem sofrer lesões permanentes com movimentos bruscos."},
  {id:"m12a4", type:"match", q:"Relacione cada situação com a conduta.", pairs:[["Perigo de desabamento","Mover o mínimo necessário para um local seguro"],["Queda de altura, sem perigo ao redor","Não mover e ligar 192"],["Motociclista de capacete respirando","Não retirar o capacete"],["Arrasto","Manter cabeça, pescoço e tronco alinhados"]], exp:"A decisão depende de haver ou não perigo imediato e de manter o alinhamento do corpo."},
  {id:"m12a5", type:"seq", q:"Ordene a decisão diante de uma vítima de queda.", items:["Avaliar a segurança da cena","Verificar se há perigo imediato","Ligar 192","Se não houver perigo, manter a vítima parada","Se houver perigo, arrastar pelo eixo até local seguro"], exp:"A segurança e a avaliação de perigo vêm antes; sem perigo, não mover; com perigo, mover o mínimo e em alinhamento."},
  {id:"m12a6", type:"essay", q:"Explique por que a movimentação inadequada pode ser perigosa e quando ela é justificável.", exp:"Esperado: lesões ocultas, principalmente de coluna, podem se agravar e causar paralisia; só justifica mover em perigo imediato (fogo, desabamento, trânsito, gás) ou necessidade de RCP; mover o mínimo e alinhado."}
 ],
 assessment:[
  {id:"m12s1", type:"mc", q:"Qual situação justifica mover rapidamente a vítima?", options:["Ela reclama de dor leve","Há risco de incêndio ou desabamento no local","Ela está com frio","Há muitos curiosos"], answer:1, exp:"Só perigo imediato à vida justifica mover. Dor leve ou frio não são motivos."},
  {id:"m12s2", type:"mc", q:"Como é feito o arrasto básico de emergência?", options:["Pelos pés, de qualquer jeito","Levantando a vítima no colo e torcendo o tronco","Pelo eixo longo do corpo, mantendo cabeça, pescoço e tronco alinhados","Sentando a vítima e puxando pelos braços de lado"], answer:2, exp:"O alinhamento de cabeça, pescoço e tronco reduz o risco de agravar lesões na coluna."},
  {id:"m12s3", type:"mc", q:"O que o leigo deve fazer quanto ao capacete de um motociclista acidentado que respira?", options:["Não retirar e ligar 192","Retirar puxando rápido","Retirar para ele respirar melhor","Girar o capacete para soltar"], answer:0, exp:"O capacete só é retirado se houver necessidade de via aérea ou RCP, de preferência por quem foi treinado."},
  {id:"m12s4", type:"tf", q:"A melhor escolha, na maioria dos casos, é esperar a equipe do 192, que tem treino e equipamentos para remover a vítima.", answer:true, exp:"Profissionais usam prancha, colar e técnicas que reduzem o risco de agravar lesões."},
  {id:"m12s5", type:"err", q:"Encontre a afirmação INCORRETA sobre remoção de vítimas.", items:["Sem perigo imediato, não se deve mover a vítima","Movimentos bruscos podem lesionar a coluna","O arrasto deve manter o corpo alinhado","Toda vítima deve ser levantada rapidamente e levada no carro"], answer:3, exp:"Levantar e transportar sem necessidade pode agravar lesões. A regra é não mover sem necessidade."},
  {id:"m12s6", type:"short", q:"Qual número você liga para acionar uma equipe capacitada de resgate médico?", answers:["192"], exp:"O 192 aciona o SAMU. Em resgates e incêndios, os Bombeiros (193) também atuam."}
 ]
};

